# Generated from tools/data/rulebooks/bridge.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Bridge
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("The aim"),
            GameRoomRules.translate("Bridge is played by four people in two partnerships. You and your partner bid for a contract: a promise to win a certain number of tricks. A trick is the four cards played in turn, one from each hand. If your pair wins the auction, you try to fulfil that promise; otherwise, you try to stop the other pair."),
            GameRoomRules.translate("The default game is a rubber. It ends when a pair has won two games, and the pair with more points overall wins the match. The scoring chapters explain how individual deals build towards that result.")),
          rule_section(:deal, GameRoomRules.translate("Your hand and your partner"),
            GameRoomRules.translate("North and South form one pair; East and West form the other. The teams chosen at the table determine these partnerships. Play follows the order North, East, South, West. Press I to hear your position and partner."),
            GameRoomRules.translate("Everyone receives 13 cards. In each suit, the order from highest to lowest is ace, king, queen, jack, 10, 9 and so on down to 2. Browse your cards with the arrows; H reads the whole hand."),
            GameRoomRules.translate("H also gives your high card points: 4 for an ace, 3 for a king, 2 for a queen and 1 for a jack. These help you judge your hand during bidding; they are separate from the match score.")),
          rule_section(:auction, GameRoomRules.translate("Bidding for a contract"),
            GameRoomRules.translate("The dealer makes the first call. On your turn, choose a call with the arrows and confirm with Enter. B also opens the bidding choices."),
            GameRoomRules.translate("A bid consists of a number from 1 to 7 and a suit, or no trump. Add six to the number to find your target: 1 heart promises seven tricks, while 4 spades promises ten. The named suit becomes trumps, whose cards can beat cards of the other suits. A no-trump contract has no such suit."),
            GameRoomRules.translate("Each new bid must be higher than the last. At the same level, the order is clubs, diamonds, hearts, spades, no trump. Any bid at a higher level outranks those below it. After 1 spade, for example, you can bid 1 no trump or 2 clubs."),
            GameRoomRules.translate("You can also make these calls:"),
            GameRoomRules.translate("- Pass leaves the bidding to the next player. You can bid later if the auction comes back to you."),
            GameRoomRules.translate("- Double raises the rewards for making the opponents' bid and the penalties for failing. It is available after an opponent's bid, possibly followed by passes."),
            GameRoomRules.translate("- Redouble raises the stakes again after an opponent has doubled your pair's bid. A new, higher bid cancels the earlier double or redouble."),
            GameRoomRules.translate("Three consecutive passes after a bid end the auction. The last bid becomes the contract. If all four players pass before anyone bids, the deal ends without a score and the next player deals."),
            GameRoomRules.translate("L reads the auction; Ctrl+L lets you inspect its calls one by one.")),
          rule_section(:play, GameRoomRules.translate("Playing the contract"),
            GameRoomRules.translate("The declarer is the member of the winning pair who first bid the suit of the final contract, or first bid no trump if that is the contract. If North bids 1 heart and South later bids 4 hearts, North declares."),
            GameRoomRules.translate("The player after declarer leads the first card. Declarer's partner then exposes their hand: this is dummy. Everyone can read it with D, but declarer chooses its cards. K repeats the contract and the number of tricks won by declarer's pair."),
            GameRoomRules.translate("Choose a card with the arrows and play it with Enter. You must follow the suit led if you have it. Otherwise, you may play any card. The highest trump wins the trick; if no trump was played, the highest card of the led suit wins. The winner leads the next trick."),
            GameRoomRules.translate("As declarer, wait for dummy's turn, then use Tab to reach dummy's card list and select a card there. Z takes you straight to a playable card in the hand due to play; Shift+Z goes backwards. With only one possible card, Z plays it."),
            GameRoomRules.translate("C reads the current trick, F repeats the suit led, and P reads the previous trick and its winner. After all 13 tricks, the deal is scored and the next player becomes dealer.")),
          rule_section(:scoring, GameRoomRules.translate("Scoring a rubber"),
            GameRoomRules.translate("Only the tricks promised beyond the first six earn contract points. If you make your contract, they are worth:"),
            GameRoomRules.translate("- 20 each in clubs or diamonds."),
            GameRoomRules.translate("- 30 each in hearts or spades."),
            GameRoomRules.translate("- 40 for the first in no trump, then 30 each."),
            GameRoomRules.translate("A double multiplies contract points by two; a redouble multiplies them by four. These points are recorded below the line. When a pair reaches 100 below the line, in one deal or several, it wins a game. Both pairs then start the next game from zero towards that target."),
            GameRoomRules.translate("For example, making 2 hearts earns 60 below the line. Making 1 no trump in a later deal adds 40 and completes the game, provided neither pair has completed a game in between."),
            GameRoomRules.translate("A pair that has won a game becomes vulnerable for the rest of the rubber. Vulnerability increases some bonuses and penalties. V reads the current deal and vulnerability."),
            GameRoomRules.translate("The first pair to win two games ends the rubber and receives a bonus: 700 if the opponents won none, or 500 if they won one. All points, including the bonuses described next, count towards the final total. The higher total wins; equal totals are a draw. S reads the scores.")),
          rule_section(:bonuses, GameRoomRules.translate("Extra tricks and penalties"),
            GameRoomRules.translate("Bonuses and penalties are recorded above the line. They count towards your total but not towards the 100 points needed to win a game."),
            GameRoomRules.translate("- Each overtrick, beyond your contract, earns 20 in clubs or diamonds and 30 in hearts, spades or no trump."),
            GameRoomRules.translate("- With a doubled contract, each overtrick earns 100, or 200 if vulnerable. Redoubling makes those amounts 200 and 400."),
            GameRoomRules.translate("- Making a doubled contract adds 50; making a redoubled contract adds 100."),
            GameRoomRules.translate("- Bidding and making 6, a small slam, earns a bonus of 500, or 750 if vulnerable. Bidding and making 7, a grand slam, earns 1000, or 1500 if vulnerable."),
            GameRoomRules.translate("If your pair wins fewer tricks than promised, the opponents receive points for the shortfall:"),
            GameRoomRules.translate("- Without a double: 50 for each missing trick, or 100 if your pair is vulnerable."),
            GameRoomRules.translate("- Doubled, not vulnerable: 100 for the first missing trick, 200 each for the second and third, and 300 each after that."),
            GameRoomRules.translate("- Doubled and vulnerable: 200 for the first missing trick and 300 each after that."),
            GameRoomRules.translate("- Redoubled: twice the corresponding doubled penalty.")),
          rule_section(:honors, GameRoomRules.translate("Honours"),
            GameRoomRules.translate("A strong group of cards in one hand can earn a separate bonus, even if its owner is defending:"),
            GameRoomRules.translate("- Four of the five highest trumps \u2014 ace, king, queen, jack and 10 \u2014 earn 100 points. All five earn 150."),
            GameRoomRules.translate("- In a no-trump contract, all four aces in one hand earn 150."),
            GameRoomRules.translate("These points go above the line. Table settings let you turn honours off.")),
          rule_section(:variants, GameRoomRules.translate("Comparison with an estimated score"),
            GameRoomRules.translate("Instead of a rubber, table settings offer a fixed series of 4, 8, 12, 16 or 24 boards; the default is 8. In this variant, each board is scored separately. The board number determines the dealer and vulnerability. V reads them."),
            GameRoomRules.translate("A contract worth at least 100 contract points earns a game bonus of 300, or 500 if vulnerable. A smaller contract earns 50. Overtricks, doubles, slams and penalties keep the values described above. There are no honours or rubber bonuses."),
            GameRoomRules.translate("Your result is then compared with a conventional reference score based on the stronger pair's combined high card points and vulnerability. This is an estimate, not a result from another table. It ignores suit lengths and how well the partners' hands fit."),
            GameRoomRules.translate("For example, a pair with 26 high card points has a reference of 400 when not vulnerable or 600 when vulnerable. At 20 points each, the reference is zero. Even a passed-out board is compared: its actual result is zero."),
            GameRoomRules.translate("Choose one of two ways to count that comparison:"),
            GameRoomRules.translate("- IMPs convert the difference into points. A difference of up to 10 earns none; 20\u201340 earns 1, 50\u201380 earns 2 and 90\u2013120 earns 3. Larger differences earn more, up to 24. The pair that outperforms the reference receives those points."),
            GameRoomRules.translate("- Matchpoints give 2 to the pair that outperforms the reference and 0 to the other pair. An equal result gives 1 each. S also presents the total as a percentage of the available points."),
            GameRoomRules.translate("After the agreed number of boards, the pair with the higher total wins. Equal totals are a draw.")),
          rule_section(:bots, GameRoomRules.translate("Bidding with a bot"),
            GameRoomRules.translate("A bot uses its own cards, the exposed dummy and the public auction and play. Its natural bidding system includes these common openings:"),
            GameRoomRules.translate("- 1 no trump shows a balanced hand with 15\u201317 high card points; 2 no trump shows 20\u201321."),
            GameRoomRules.translate("- 1 heart or 1 spade usually shows at least 12 points and five cards in that suit. Without a five-card major, the bot opens a minor suit."),
            GameRoomRules.translate("- 2 diamonds, 2 hearts or 2 spades shows a six-card suit and 6\u201310 points."),
            GameRoomRules.translate("A raise of your suit shows support. Raising to two is weak; raising to three invites game. Bots do not double.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard shortcuts"),
            GameRoomRules.translate("Arrows: browse cards or calls."),
            GameRoomRules.translate("Enter: make the selected call or play the selected card."),
            GameRoomRules.translate("B: choose a call on your bidding turn; otherwise read the auction."),
            GameRoomRules.translate("L: read the auction."),
            GameRoomRules.translate("Ctrl+L: inspect the auction."),
            GameRoomRules.translate("H: read your hand and high card points."),
            GameRoomRules.translate("D: read dummy's cards."),
            GameRoomRules.translate("Tab: move between card lists."),
            GameRoomRules.translate("Z: find the next playable card; play it if it is the only one."),
            GameRoomRules.translate("Shift+Z: find the previous playable card."),
            GameRoomRules.translate("K: read the contract and declarer's trick count."),
            GameRoomRules.translate("C: read the current trick."),
            GameRoomRules.translate("Ctrl+C: inspect the current trick."),
            GameRoomRules.translate("F: read the suit led."),
            GameRoomRules.translate("P: read the previous trick."),
            GameRoomRules.translate("I: read your position, partner and role."),
            GameRoomRules.translate("V: read the deal, vulnerability and contract."),
            GameRoomRules.translate("S: read the scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("Shift+C: sort cards by suit."),
            GameRoomRules.translate("Shift+H: sort cards by rank."),
            GameRoomRules.translate("Shift+M: restore received order."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "Brid\u017E hraj\u00ED \u010Dty\u0159i hr\u00E1\u010Di ve dvou dvojic\u00EDch. S partnerem se nejprve v licitaci zav\u00E1\u017Eete z\u00EDskat ur\u010Dit\u00FD po\u010Det zdvih\u016F. Zdvih tvo\u0159\u00ED \u010Dty\u0159i karty, po jedn\u00E9 od ka\u017Ed\u00E9ho hr\u00E1\u010De. Dvojice, kter\u00E1 vyhraje licitaci, se sna\u017E\u00ED sv\u016Fj z\u00E1vazek splnit; soupe\u0159i j\u00ED v tom br\u00E1n\u00ED.",
              "Ve v\u00FDchoz\u00EDm nastaven\u00ED hrajete robra. Kon\u010D\u00ED, kdy\u017E jedna dvojice vyhraje dv\u011B hry. O v\u00EDt\u011Bzi cel\u00E9ho z\u00E1pasu rozhoduje sou\u010Det bod\u016F, nikoli samotn\u00FD po\u010Det vyhran\u00FDch her."),
            rule_section(:deal, "Karty a partner",
              "Sever hraje s Jihem, V\u00FDchod se Z\u00E1padem. Partnery ur\u010Duje rozd\u011Blen\u00ED do t\u00FDm\u016F u stolu. Na tahu se st\u0159\u00EDdaj\u00ED Sever, V\u00FDchod, Jih a Z\u00E1pad. Kl\u00E1vesa I p\u0159ipomene va\u0161e m\u00EDsto i partnera.",
              "Ka\u017Ed\u00FD dostane 13 karet. Nejvy\u0161\u0161\u00ED kartou v ka\u017Ed\u00E9 barv\u011B je eso, pak n\u00E1sleduj\u00ED kr\u00E1l, d\u00E1ma, kluk, des\u00EDtka a ostatn\u00ED karty a\u017E po dvojku. Karty proch\u00E1z\u00EDte \u0161ipkami; H p\u0159e\u010Dte celou ruku.",
              "P\u0159i \u010Dten\u00ED ruky usly\u0161\u00EDte tak\u00E9 figurov\u00E9 body: eso m\u00E1 4, kr\u00E1l 3, d\u00E1ma 2 a kluk 1. Pom\u00E1haj\u00ED odhadnout s\u00EDlu karet pro licitaci, ale nep\u0159i\u010D\u00EDtaj\u00ED se ke sk\u00F3re z\u00E1pasu."),
            rule_section(:auction, "Licitace",
              "Za\u010D\u00EDn\u00E1 rozd\u00E1vaj\u00EDc\u00ED. Na sv\u00E9m tahu vyberte hl\u00E1\u0161ku \u0161ipkami a potvr\u010Fte Enterem. Nab\u00EDdku hl\u00E1\u0161ek otev\u0159ete tak\u00E9 kl\u00E1vesou B.",
              "Nab\u00EDdka obsahuje \u010D\u00EDslo od 1 do 7 a barvu, p\u0159\u00EDpadn\u011B bez trumf\u016F. K \u010D\u00EDslu p\u0159i\u010Dt\u011Bte \u0161est: 1 srdce slibuje sedm zdvih\u016F, 4 piky deset. Zvolen\u00E1 barva je trumfov\u00E1, tak\u017Ee jej\u00ED karty mohou p\u0159eb\u00EDt ostatn\u00ED barvy. P\u0159i h\u0159e bez trumf\u016F tuto v\u00FDhodu nem\u00E1 \u017E\u00E1dn\u00E1 barva.",
              "Nov\u00E1 nab\u00EDdka mus\u00ED b\u00FDt vy\u0161\u0161\u00ED ne\u017E p\u0159edchoz\u00ED. Na stejn\u00E9m stupni je po\u0159ad\u00ED trefy, k\u00E1ra, srdce, piky, bez trumf\u016F. Vy\u0161\u0161\u00ED stupe\u0148 p\u0159ekon\u00E1 v\u0161echny ni\u017E\u0161\u00ED nab\u00EDdky. Po 1 piku tedy m\u016F\u017Eete nab\u00EDdnout 1 bez trumf\u016F nebo 2 trefy.",
              "Krom\u011B nov\u00E9 nab\u00EDdky m\u016F\u017Eete zvolit:",
              "- Pas: p\u0159enech\u00E1te slovo dal\u0161\u00EDmu hr\u00E1\u010Di. A\u017E na v\u00E1s znovu p\u0159ijde \u0159ada, m\u016F\u017Eete licitovat d\u00E1l.",
              "- Kontra: zv\u00FD\u0161\u00EDte odm\u011Bnu za spln\u011Bn\u00ED soupe\u0159ova z\u00E1vazku i trest za jeho nespln\u011Bn\u00ED. Kontrujete posledn\u00ED soupe\u0159ovu nab\u00EDdku, po kter\u00E9 p\u0159\u00EDpadn\u011B zazn\u011Bly pasy.",
              "- Rekontra: pokud soupe\u0159 kontroval nab\u00EDdku va\u0161\u00ED dvojice, je\u0161t\u011B zv\u00FD\u0161\u00EDte s\u00E1zku. Nov\u00E1 vy\u0161\u0161\u00ED nab\u00EDdka p\u0159edchoz\u00ED kontru i rekontru ru\u0161\u00ED.",
              "Po nab\u00EDdce ukon\u010D\u00ED licitaci t\u0159i pasy za sebou. Posledn\u00ED nab\u00EDdka ur\u010D\u00ED z\u00E1vazek. Pokud na za\u010D\u00E1tku pasuj\u00ED v\u0161ichni \u010Dty\u0159i hr\u00E1\u010Di, rozd\u00E1n\u00ED skon\u010D\u00ED bez bod\u016F a rozd\u00E1v\u00E1 dal\u0161\u00ED hr\u00E1\u010D.",
              "Kl\u00E1vesa L p\u0159e\u010Dte licitaci; pomoc\u00ED Ctrl+L ji m\u016F\u017Eete proj\u00EDt po jednotliv\u00FDch hl\u00E1\u0161k\u00E1ch."),
            rule_section(:play, "Sehr\u00E1vka a tich\u00FD hr\u00E1\u010D",
              "Hlavn\u00EDm hr\u00E1\u010Dem je ten z v\u00EDt\u011Bzn\u00E9 dvojice, kdo jako prvn\u00ED nab\u00EDdl barvu kone\u010Dn\u00E9ho z\u00E1vazku, nebo bez trumf\u016F, pokud je takov\u00FD z\u00E1vazek. Kdy\u017E Sever nab\u00EDdne 1 srdce a Jih pozd\u011Bji 4 srdce, hlavn\u00EDm hr\u00E1\u010Dem je Sever.",
              "Prvn\u00ED kartu vyn\u00E1\u0161\u00ED hr\u00E1\u010D n\u00E1sleduj\u00EDc\u00ED po hlavn\u00EDm hr\u00E1\u010Di. Pot\u00E9 partner hlavn\u00EDho hr\u00E1\u010De odkryje karty a st\u00E1v\u00E1 se tich\u00FDm hr\u00E1\u010Dem. Jeho ruku si ka\u017Ed\u00FD m\u016F\u017Ee p\u0159e\u010D\u00EDst kl\u00E1vesou D, ale karty z n\u00ED vyb\u00EDr\u00E1 hlavn\u00ED hr\u00E1\u010D. K p\u0159ipomene z\u00E1vazek a z\u00EDskan\u00E9 zdvihy jeho dvojice.",
              "Kartu vyberte \u0161ipkami a zahrajte Enterem. M\u00E1te-li barvu prvn\u00ED karty ve zdvihu, mus\u00EDte ji p\u0159iznat. Jinak m\u016F\u017Eete zahr\u00E1t libovolnou kartu. Zdvih z\u00EDsk\u00E1 nejvy\u0161\u0161\u00ED trumf; pokud \u017E\u00E1dn\u00FD nepadl, nejvy\u0161\u0161\u00ED karta vynesen\u00E9 barvy. V\u00EDt\u011Bz zdvihu vyn\u00E1\u0161\u00ED dal\u0161\u00ED kartu.",
              "Jako hlavn\u00ED hr\u00E1\u010D hrajete tak\u00E9 za sv\u00E9ho partnera. Kdy\u017E p\u0159ijde na \u0159adu tich\u00FD hr\u00E1\u010D, p\u0159ejd\u011Bte Tabem do seznamu jeho karet a jednu vyberte. Z v\u00E1s p\u0159enese na p\u0159\u00EDpustnou kartu ve spr\u00E1vn\u00E9 ruce, Shift+Z hled\u00E1 opa\u010Dn\u00FDm sm\u011Brem. Je-li p\u0159\u00EDpustn\u00E1 jen jedna karta, Z ji rovnou zahraje.",
              "C p\u0159e\u010Dte pr\u00E1v\u011B hran\u00FD zdvih, F p\u0159ipomene vynesenou barvu a P p\u0159edchoz\u00ED zdvih i jeho v\u00EDt\u011Bze. Po t\u0159in\u00E1cti zdviz\u00EDch se rozd\u00E1n\u00ED vyhodnot\u00ED a rozd\u00E1v\u00E1 dal\u0161\u00ED hr\u00E1\u010D."),
            rule_section(:scoring, "Body a robr",
              "Spln\u011Bn\u00FD z\u00E1vazek p\u0159in\u00E1\u0161\u00ED body za sl\u00EDben\u00E9 zdvihy nad prvn\u00EDch \u0161est:",
              "- V trefech a k\u00E1rech po 20 bodech.",
              "- V srdc\u00EDch a pik\u00E1ch po 30 bodech.",
              "- Bez trumf\u016F 40 za prvn\u00ED a po 30 za dal\u0161\u00ED.",
              "Kontra tyto body zdvojn\u00E1sob\u00ED, rekontra je n\u00E1sob\u00ED \u010Dty\u0159mi. Zapisuj\u00ED se pod \u010D\u00E1ru. Dvojice vyhraje hru, jakmile takto z\u00EDsk\u00E1 100 bod\u016F v jednom \u010Di v\u00EDce rozd\u00E1n\u00EDch. Pro dal\u0161\u00ED hru pak ob\u011B dvojice za\u010D\u00EDnaj\u00ED po\u010D\u00EDtat znovu od nuly.",
              "Nap\u0159\u00EDklad spln\u011Bn\u00E1 2 srdce d\u00E1vaj\u00ED 60 bod\u016F pod \u010Darou. Pozd\u011Bj\u0161\u00ED 1 bez trumf\u016F p\u0159id\u00E1 40 a dokon\u010D\u00ED hru, pokud mezit\u00EDm hru nevyhr\u00E1la n\u011Bkter\u00E1 dvojice.",
              "Po vyhran\u00E9 h\u0159e je dvojice ve druh\u00E9 h\u0159e a\u017E do konce robra. Zvy\u0161uj\u00ED se j\u00ED n\u011Bkter\u00E9 pr\u00E9mie i tresty. Kl\u00E1vesa V p\u0159e\u010Dte rozd\u00E1n\u00ED a to, kter\u00E9 dvojice jsou ve druh\u00E9 h\u0159e.",
              "Druh\u00E1 vyhran\u00E1 hra ukon\u010D\u00ED robra. Za jeho v\u00EDt\u011Bzstv\u00ED dostane dvojice 700 bod\u016F, pokud soupe\u0159i nevyhr\u00E1li \u017E\u00E1dnou hru, nebo 500, pokud vyhr\u00E1li jednu. Z\u00E1pas vyhraje vy\u0161\u0161\u00ED sou\u010Det v\u0161ech bod\u016F v\u010Detn\u011B pr\u00E9mi\u00ED. P\u0159i shod\u011B je rem\u00EDza. Sk\u00F3re p\u0159e\u010Dte S."),
            rule_section(:bonuses, "Nadzdvihy, pr\u00E9mie a p\u00E1dy",
              "Pr\u00E9mie i trestn\u00E9 body se zapisuj\u00ED nad \u010D\u00E1ru. Zvy\u0161uj\u00ED celkov\u00E9 sk\u00F3re, ale nepo\u010D\u00EDtaj\u00ED se do sta bod\u016F pot\u0159ebn\u00FDch k vyhr\u00E1n\u00ED hry.",
              "- Zdvih nad z\u00E1vazek d\u00E1v\u00E1 20 bod\u016F v trefech \u010Di k\u00E1rech a 30 v srdc\u00EDch, pik\u00E1ch \u010Di bez trumf\u016F.",
              "- S kontrou m\u00E1 nadzdvih cenu 100 bod\u016F v prvn\u00ED h\u0159e nebo 200 ve druh\u00E9. S rekontrou jsou \u010D\u00E1stky 200 a 400.",
              "- Spln\u011Bn\u00ED kontrovan\u00E9ho z\u00E1vazku p\u0159id\u00E1v\u00E1 50 bod\u016F, rekontrovan\u00E9ho 100.",
              "- Vylicitovan\u00FD a spln\u011Bn\u00FD mal\u00FD slem, tedy z\u00E1vazek na \u0161est\u00E9m stupni, p\u0159in\u00E1\u0161\u00ED pr\u00E9mii 500 v prvn\u00ED h\u0159e nebo 750 ve druh\u00E9. Velk\u00FD slem na sedm\u00E9m stupni d\u00E1v\u00E1 1000 nebo 1500.",
              "Pokud z\u00EDsk\u00E1te m\u00E9n\u011B zdvih\u016F, ne\u017E jste sl\u00EDbili, soupe\u0159i obdr\u017E\u00ED body za ka\u017Ed\u00FD chyb\u011Bj\u00EDc\u00ED zdvih:",
              "- Bez kontry: po 50 bodech v prvn\u00ED h\u0159e, po 100 ve druh\u00E9.",
              "- S kontrou v prvn\u00ED h\u0159e: 100 za prvn\u00ED p\u00E1d, po 200 za druh\u00FD a t\u0159et\u00ED, potom po 300.",
              "- S kontrou ve druh\u00E9 h\u0159e: 200 za prvn\u00ED p\u00E1d, potom po 300.",
              "- S rekontrou: dvojn\u00E1sobek p\u0159\u00EDslu\u0161n\u00E9ho trestu s kontrou."),
            rule_section(:honors, "Hon\u00E9ry",
              "Samostatnou pr\u00E9mii m\u016F\u017Ee z\u00EDskat dvojice za vysok\u00E9 karty v jedn\u00E9 ruce, i kdy\u017E br\u00E1n\u00ED:",
              "- \u010Cty\u0159i z p\u011Bti nejvy\u0161\u0161\u00EDch trumf\u016F \u2014 esa, kr\u00E1le, d\u00E1my, kluka a des\u00EDtky \u2014 d\u00E1vaj\u00ED 100 bod\u016F. V\u0161ech p\u011Bt d\u00E1v\u00E1 150.",
              "- P\u0159i z\u00E1vazku bez trumf\u016F d\u00E1vaj\u00ED \u010Dty\u0159i esa v jedn\u00E9 ruce 150 bod\u016F.",
              "Hon\u00E9ry se zapisuj\u00ED nad \u010D\u00E1ru. Jejich bodov\u00E1n\u00ED lze v nastaven\u00ED stolu vypnout."),
            rule_section(:variants, "Srovn\u00E1n\u00ED s orienta\u010Dn\u00EDm v\u00FDsledkem",
              "M\u00EDsto robra lze v nastaven\u00ED stolu vybrat s\u00E9rii 4, 8, 12, 16 nebo 24 rozd\u00E1n\u00ED; v\u00FDchoz\u00ED po\u010Det je 8. Ka\u017Ed\u00E9 rozd\u00E1n\u00ED se hodnot\u00ED samostatn\u011B. Jeho \u010D\u00EDslo ur\u010Duje rozd\u00E1vaj\u00EDc\u00EDho a stav prvn\u00ED \u010Di druh\u00E9 hry. Tyto \u00FAdaje p\u0159e\u010Dte V.",
              "Za z\u00E1vazek s alespo\u0148 100 body za sl\u00EDben\u00E9 zdvihy dostanete pr\u00E9mii za man\u0161: 300 v prvn\u00ED h\u0159e nebo 500 ve druh\u00E9. Men\u0161\u00ED z\u00E1vazek p\u0159in\u00E1\u0161\u00ED 50. Nadzdvihy, kontry, slemy a p\u00E1dy se po\u010D\u00EDtaj\u00ED jako v\u00FD\u0161e; hon\u00E9ry ani pr\u00E9mie za robra tu nejsou.",
              "V\u00FDsledek se porovn\u00E1 se smluven\u00FDm odhadem podle sou\u010Dtu figurov\u00FDch bod\u016F siln\u011Bj\u0161\u00ED dvojice a jej\u00EDho stavu prvn\u00ED \u010Di druh\u00E9 hry. Nejde o skute\u010Dn\u00FD v\u00FDsledek jin\u00E9ho stolu. Odhad nezohled\u0148uje d\u00E9lku barev ani to, jak se karty partner\u016F dopl\u0148uj\u00ED.",
              "P\u0159i 26 figurov\u00FDch bodech je nap\u0159\u00EDklad orienta\u010Dn\u00ED v\u00FDsledek 400 v prvn\u00ED h\u0159e a 600 ve druh\u00E9. Maj\u00ED-li ob\u011B dvojice po 20 bodech, je nulov\u00FD. Porovn\u00E1v\u00E1 se i rozd\u00E1n\u00ED, ve kter\u00E9m v\u0161ichni pasovali: jeho skute\u010Dn\u00FD v\u00FDsledek je nula.",
              "Zvolit m\u016F\u017Eete tyto zp\u016Fsoby p\u0159epo\u010Dtu:",
              "- IMP: rozd\u00EDl do 10 bod\u016F nep\u0159in\u00E1\u0161\u00ED nic, 20\u201340 d\u00E1v\u00E1 1 IMP, 50\u201380 d\u00E1v\u00E1 2 a 90\u2013120 d\u00E1v\u00E1 3. V\u011Bt\u0161\u00ED rozd\u00EDly p\u0159in\u00E1\u0161ej\u00ED v\u00EDce, nejv\u00FD\u0161e 24 IMP. Z\u00EDsk\u00E1 je dvojice, kter\u00E1 dopadla l\u00E9pe ne\u017E orienta\u010Dn\u00ED v\u00FDsledek.",
              "- Matchpointy: lep\u0161\u00ED v\u00FDsledek ne\u017E odhad d\u00E1v\u00E1 dvojici 2 body a soupe\u0159\u016Fm 0. P\u0159i rovnosti z\u00EDsk\u00E1 ka\u017Ed\u00E1 dvojice 1 bod. S p\u0159e\u010Dte sk\u00F3re tak\u00E9 jako procento mo\u017En\u00FDch bod\u016F.",
              "Po posledn\u00EDm rozd\u00E1n\u00ED vyhraje dvojice s vy\u0161\u0161\u00EDm sou\u010Dtem. Stejn\u00FD sou\u010Det znamen\u00E1 rem\u00EDzu."),
            rule_section(:bots, "Licitace s botem",
              "Bot zn\u00E1 vlastn\u00ED karty, odkrytou ruku tich\u00E9ho hr\u00E1\u010De a ve\u0159ejnou licitaci i zahran\u00E9 karty. Pou\u017E\u00EDv\u00E1 p\u0159irozenou licitaci. B\u011B\u017En\u00E1 zah\u00E1jen\u00ED znamenaj\u00ED:",
              "- 1 bez trumf\u016F: vyv\u00E1\u017Een\u00E1 ruka s 15\u201317 figurov\u00FDmi body; 2 bez trumf\u016F: 20\u201321 bod\u016F.",
              "- 1 srdce nebo 1 pik: obvykle alespo\u0148 12 bod\u016F a p\u011Bt karet v barv\u011B. Bez p\u011Bti srdc\u00ED \u010Di pik\u016F bot zah\u00E1j\u00ED levnou barvou.",
              "- 2 k\u00E1ra, 2 srdce nebo 2 piky: \u0161est karet v barv\u011B a 6\u201310 bod\u016F.",
              "Zv\u00FD\u0161en\u00ED va\u0161\u00ED barvy znamen\u00E1 podporu. Zv\u00FD\u0161en\u00ED na druh\u00FD stupe\u0148 je slab\u00E9, na t\u0159et\u00ED vyb\u00EDz\u00ED k man\u0161i. Boti nekontruj\u00ED."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: proch\u00E1zen\u00ED karet nebo hl\u00E1\u0161ek.",
              "Enter: vybran\u00E1 hl\u00E1\u0161ka nebo zahr\u00E1n\u00ED karty.",
              "B: v\u00FDb\u011Br hl\u00E1\u0161ky na sv\u00E9m tahu; jinak p\u0159e\u010Dten\u00ED licitace.",
              "L: p\u0159e\u010Dten\u00ED licitace.",
              "Ctrl+L: proch\u00E1zen\u00ED licitace.",
              "H: vlastn\u00ED karty a figurov\u00E9 body.",
              "D: karty tich\u00E9ho hr\u00E1\u010De.",
              "Tab: p\u0159echod mezi seznamy karet.",
              "Z: dal\u0161\u00ED p\u0159\u00EDpustn\u00E1 karta; jedinou mo\u017Enou rovnou zahraje.",
              "Shift+Z: p\u0159edchoz\u00ED p\u0159\u00EDpustn\u00E1 karta.",
              "K: z\u00E1vazek a po\u010Det z\u00EDskan\u00FDch zdvih\u016F.",
              "C: pr\u00E1v\u011B hran\u00FD zdvih.",
              "Ctrl+C: proch\u00E1zen\u00ED karet zdvihu.",
              "F: vynesen\u00E1 barva.",
              "P: p\u0159edchoz\u00ED zdvih.",
              "I: va\u0161e m\u00EDsto, partner a role.",
              "V: rozd\u00E1n\u00ED, stav prvn\u00ED \u010Di druh\u00E9 hry a z\u00E1vazek.",
              "S: sk\u00F3re.",
              "T: kdo je na tahu.",
              "Shift+C: \u0159azen\u00ED karet podle barvy.",
              "Shift+H: \u0159azen\u00ED podle hodnoty.",
              "Shift+M: p\u016Fvodn\u00ED po\u0159ad\u00ED karet.")
          ]
        when "en"
          [
            rule_section(:aim, "The aim",
              "Bridge is played by four people in two partnerships. You and your partner bid for a contract: a promise to win a certain number of tricks. A trick is the four cards played in turn, one from each hand. If your pair wins the auction, you try to fulfil that promise; otherwise, you try to stop the other pair.",
              "The default game is a rubber. It ends when a pair has won two games, and the pair with more points overall wins the match. The scoring chapters explain how individual deals build towards that result."),
            rule_section(:deal, "Your hand and your partner",
              "North and South form one pair; East and West form the other. The teams chosen at the table determine these partnerships. Play follows the order North, East, South, West. Press I to hear your position and partner.",
              "Everyone receives 13 cards. In each suit, the order from highest to lowest is ace, king, queen, jack, 10, 9 and so on down to 2. Browse your cards with the arrows; H reads the whole hand.",
              "H also gives your high card points: 4 for an ace, 3 for a king, 2 for a queen and 1 for a jack. These help you judge your hand during bidding; they are separate from the match score."),
            rule_section(:auction, "Bidding for a contract",
              "The dealer makes the first call. On your turn, choose a call with the arrows and confirm with Enter. B also opens the bidding choices.",
              "A bid consists of a number from 1 to 7 and a suit, or no trump. Add six to the number to find your target: 1 heart promises seven tricks, while 4 spades promises ten. The named suit becomes trumps, whose cards can beat cards of the other suits. A no-trump contract has no such suit.",
              "Each new bid must be higher than the last. At the same level, the order is clubs, diamonds, hearts, spades, no trump. Any bid at a higher level outranks those below it. After 1 spade, for example, you can bid 1 no trump or 2 clubs.",
              "You can also make these calls:",
              "- Pass leaves the bidding to the next player. You can bid later if the auction comes back to you.",
              "- Double raises the rewards for making the opponents' bid and the penalties for failing. It is available after an opponent's bid, possibly followed by passes.",
              "- Redouble raises the stakes again after an opponent has doubled your pair's bid. A new, higher bid cancels the earlier double or redouble.",
              "Three consecutive passes after a bid end the auction. The last bid becomes the contract. If all four players pass before anyone bids, the deal ends without a score and the next player deals.",
              "L reads the auction; Ctrl+L lets you inspect its calls one by one."),
            rule_section(:play, "Playing the contract",
              "The declarer is the member of the winning pair who first bid the suit of the final contract, or first bid no trump if that is the contract. If North bids 1 heart and South later bids 4 hearts, North declares.",
              "The player after declarer leads the first card. Declarer's partner then exposes their hand: this is dummy. Everyone can read it with D, but declarer chooses its cards. K repeats the contract and the number of tricks won by declarer's pair.",
              "Choose a card with the arrows and play it with Enter. You must follow the suit led if you have it. Otherwise, you may play any card. The highest trump wins the trick; if no trump was played, the highest card of the led suit wins. The winner leads the next trick.",
              "As declarer, wait for dummy's turn, then use Tab to reach dummy's card list and select a card there. Z takes you straight to a playable card in the hand due to play; Shift+Z goes backwards. With only one possible card, Z plays it.",
              "C reads the current trick, F repeats the suit led, and P reads the previous trick and its winner. After all 13 tricks, the deal is scored and the next player becomes dealer."),
            rule_section(:scoring, "Scoring a rubber",
              "Only the tricks promised beyond the first six earn contract points. If you make your contract, they are worth:",
              "- 20 each in clubs or diamonds.",
              "- 30 each in hearts or spades.",
              "- 40 for the first in no trump, then 30 each.",
              "A double multiplies contract points by two; a redouble multiplies them by four. These points are recorded below the line. When a pair reaches 100 below the line, in one deal or several, it wins a game. Both pairs then start the next game from zero towards that target.",
              "For example, making 2 hearts earns 60 below the line. Making 1 no trump in a later deal adds 40 and completes the game, provided neither pair has completed a game in between.",
              "A pair that has won a game becomes vulnerable for the rest of the rubber. Vulnerability increases some bonuses and penalties. V reads the current deal and vulnerability.",
              "The first pair to win two games ends the rubber and receives a bonus: 700 if the opponents won none, or 500 if they won one. All points, including the bonuses described next, count towards the final total. The higher total wins; equal totals are a draw. S reads the scores."),
            rule_section(:bonuses, "Extra tricks and penalties",
              "Bonuses and penalties are recorded above the line. They count towards your total but not towards the 100 points needed to win a game.",
              "- Each overtrick, beyond your contract, earns 20 in clubs or diamonds and 30 in hearts, spades or no trump.",
              "- With a doubled contract, each overtrick earns 100, or 200 if vulnerable. Redoubling makes those amounts 200 and 400.",
              "- Making a doubled contract adds 50; making a redoubled contract adds 100.",
              "- Bidding and making 6, a small slam, earns a bonus of 500, or 750 if vulnerable. Bidding and making 7, a grand slam, earns 1000, or 1500 if vulnerable.",
              "If your pair wins fewer tricks than promised, the opponents receive points for the shortfall:",
              "- Without a double: 50 for each missing trick, or 100 if your pair is vulnerable.",
              "- Doubled, not vulnerable: 100 for the first missing trick, 200 each for the second and third, and 300 each after that.",
              "- Doubled and vulnerable: 200 for the first missing trick and 300 each after that.",
              "- Redoubled: twice the corresponding doubled penalty."),
            rule_section(:honors, "Honours",
              "A strong group of cards in one hand can earn a separate bonus, even if its owner is defending:",
              "- Four of the five highest trumps \u2014 ace, king, queen, jack and 10 \u2014 earn 100 points. All five earn 150.",
              "- In a no-trump contract, all four aces in one hand earn 150.",
              "These points go above the line. Table settings let you turn honours off."),
            rule_section(:variants, "Comparison with an estimated score",
              "Instead of a rubber, table settings offer a fixed series of 4, 8, 12, 16 or 24 boards; the default is 8. In this variant, each board is scored separately. The board number determines the dealer and vulnerability. V reads them.",
              "A contract worth at least 100 contract points earns a game bonus of 300, or 500 if vulnerable. A smaller contract earns 50. Overtricks, doubles, slams and penalties keep the values described above. There are no honours or rubber bonuses.",
              "Your result is then compared with a conventional reference score based on the stronger pair's combined high card points and vulnerability. This is an estimate, not a result from another table. It ignores suit lengths and how well the partners' hands fit.",
              "For example, a pair with 26 high card points has a reference of 400 when not vulnerable or 600 when vulnerable. At 20 points each, the reference is zero. Even a passed-out board is compared: its actual result is zero.",
              "Choose one of two ways to count that comparison:",
              "- IMPs convert the difference into points. A difference of up to 10 earns none; 20\u201340 earns 1, 50\u201380 earns 2 and 90\u2013120 earns 3. Larger differences earn more, up to 24. The pair that outperforms the reference receives those points.",
              "- Matchpoints give 2 to the pair that outperforms the reference and 0 to the other pair. An equal result gives 1 each. S also presents the total as a percentage of the available points.",
              "After the agreed number of boards, the pair with the higher total wins. Equal totals are a draw."),
            rule_section(:bots, "Bidding with a bot",
              "A bot uses its own cards, the exposed dummy and the public auction and play. Its natural bidding system includes these common openings:",
              "- 1 no trump shows a balanced hand with 15\u201317 high card points; 2 no trump shows 20\u201321.",
              "- 1 heart or 1 spade usually shows at least 12 points and five cards in that suit. Without a five-card major, the bot opens a minor suit.",
              "- 2 diamonds, 2 hearts or 2 spades shows a six-card suit and 6\u201310 points.",
              "A raise of your suit shows support. Raising to two is weak; raising to three invites game. Bots do not double."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrows: browse cards or calls.",
              "Enter: make the selected call or play the selected card.",
              "B: choose a call on your bidding turn; otherwise read the auction.",
              "L: read the auction.",
              "Ctrl+L: inspect the auction.",
              "H: read your hand and high card points.",
              "D: read dummy's cards.",
              "Tab: move between card lists.",
              "Z: find the next playable card; play it if it is the only one.",
              "Shift+Z: find the previous playable card.",
              "K: read the contract and declarer's trick count.",
              "C: read the current trick.",
              "Ctrl+C: inspect the current trick.",
              "F: read the suit led.",
              "P: read the previous trick.",
              "I: read your position, partner and role.",
              "V: read the deal, vulnerability and contract.",
              "S: read the scores.",
              "T: read whose turn it is.",
              "Shift+C: sort cards by suit.",
              "Shift+H: sort cards by rank.",
              "Shift+M: restore received order.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo",
              "El bridge se juega entre cuatro personas, en dos parejas. Primero participas con tu compa\u00F1ero en una subasta para comprometeros a ganar cierto n\u00FAmero de bazas. Una baza son las cuatro cartas que se juegan por turno, una de cada mano. La pareja que gana la subasta intenta cumplir su contrato y la otra trata de impedirlo.",
              "Por defecto se juega un rubber, que termina cuando una pareja gana dos mangas. Vence la pareja con m\u00E1s puntos en total; ganar las dos mangas no garantiza por s\u00ED solo la victoria."),
            rule_section(:deal, "Tu mano y tu compa\u00F1ero",
              "Norte juega con Sur, y Este con Oeste. La elecci\u00F3n de equipos de la mesa determina las parejas. Los turnos siguen el orden Norte, Este, Sur y Oeste. La tecla I te recuerda tu posici\u00F3n y qui\u00E9n es tu compa\u00F1ero.",
              "Cada jugador recibe 13 cartas. De mayor a menor, las cartas de cada palo son as, rey, dama, jota, diez y las dem\u00E1s hasta el dos. Recorre tu mano con las flechas o pulsa H para escucharla entera.",
              "H tambi\u00E9n anuncia tus puntos de honor: 4 por un as, 3 por un rey, 2 por una dama y 1 por una jota. Sirven para valorar la mano durante la subasta, no se suman a la puntuaci\u00F3n de la partida."),
            rule_section(:auction, "La subasta",
              "Empieza el repartidor. En tu turno, elige una declaraci\u00F3n con las flechas y conf\u00EDrmala con Intro. Tambi\u00E9n puedes abrir las opciones con B.",
              "Una apuesta indica un n\u00FAmero del 1 al 7 y un palo, o sin triunfo. Al n\u00FAmero se le suman seis para obtener las bazas prometidas: 1 coraz\u00F3n promete siete; 4 picas, diez. El palo elegido ser\u00E1 triunfo y sus cartas podr\u00E1n superar a las de otros palos. En un contrato sin triunfo ning\u00FAn palo tiene esa ventaja.",
              "Cada apuesta debe superar a la anterior. A igual n\u00FAmero, el orden de menor a mayor es tr\u00E9boles, diamantes, corazones, picas y sin triunfo. Un n\u00FAmero mayor supera cualquier apuesta de nivel inferior. Despu\u00E9s de 1 pica, por ejemplo, puedes declarar 1 sin triunfo o 2 tr\u00E9boles.",
              "Tambi\u00E9n puedes elegir:",
              "- Paso: cedes la palabra al siguiente jugador. Si la subasta vuelve a ti, puedes volver a apostar.",
              "- Doblo: aumentas tanto la recompensa por cumplir el contrato rival como la penalizaci\u00F3n por fallarlo. Puedes doblar la \u00FAltima apuesta de un rival, aunque despu\u00E9s haya habido pasos.",
              "- Redoblo: si un rival ha doblado la apuesta de tu pareja, vuelves a aumentar lo que est\u00E1 en juego. Una apuesta superior anula el doblo o redoblo anterior.",
              "Tres pasos seguidos despu\u00E9s de una apuesta cierran la subasta. La \u00FAltima apuesta es el contrato. Si los cuatro jugadores pasan desde el principio, el reparto termina sin puntos y reparte el siguiente jugador.",
              "L lee toda la subasta; Ctrl+L permite consultar sus declaraciones una a una."),
            rule_section(:play, "El declarante y el muerto",
              "Declara quien, dentro de la pareja ganadora, nombr\u00F3 por primera vez el palo del contrato final, o sin triunfo si ese es el contrato. Si Norte abre con 1 coraz\u00F3n y Sur termina en 4 corazones, el declarante es Norte.",
              "El jugador siguiente al declarante sale con la primera carta. Entonces el compa\u00F1ero del declarante descubre su mano: es el muerto. Todos pueden escuchar sus cartas con D, pero las juega el declarante. K recuerda el contrato y las bazas que lleva su pareja.",
              "Elige una carta con las flechas y ju\u00E9gala con Intro. Si tienes cartas del palo de salida, debes jugar una. Si no, puedes jugar cualquier carta. Gana la baza el triunfo m\u00E1s alto; si no se ha jugado ninguno, gana la carta m\u00E1s alta del palo de salida. Quien gana sale en la siguiente baza.",
              "Como declarante, cuando le toque jugar al muerto, usa Tab para pasar a su lista de cartas y elige una all\u00ED. Z busca una carta que puedas jugar en la mano a la que le toca; May\u00FAs+Z busca hacia atr\u00E1s. Si solo hay una carta posible, Z la juega directamente.",
              "C lee la baza actual, F recuerda el palo de salida y P lee la baza anterior y su ganador. Tras las 13 bazas se calculan los puntos y el siguiente jugador reparte."),
            rule_section(:scoring, "Puntuaci\u00F3n del rubber",
              "Si cumples el contrato, recibes puntos por las bazas prometidas por encima de las seis primeras:",
              "- 20 por cada baza de tr\u00E9boles o diamantes.",
              "- 30 por cada baza de corazones o picas.",
              "- Sin triunfo: 40 por la primera y 30 por cada una de las dem\u00E1s.",
              "El doblo multiplica esos puntos por dos; el redoblo, por cuatro. Se anotan debajo de la l\u00EDnea. Una pareja gana una manga al reunir 100 puntos all\u00ED, en un reparto o en varios. Despu\u00E9s ambas parejas vuelven a empezar de cero para la siguiente manga.",
              "Por ejemplo, cumplir 2 corazones da 60 puntos debajo de la l\u00EDnea. Cumplir m\u00E1s adelante 1 sin triunfo a\u00F1ade 40 y completa la manga, siempre que ninguna pareja haya ganado una manga entre ambos repartos.",
              "Una pareja que ha ganado una manga pasa a ser vulnerable hasta el final del rubber. Esto aumenta algunas primas y penalizaciones. V anuncia el reparto y la vulnerabilidad.",
              "La segunda manga ganada termina el rubber. Su ganador recibe 700 puntos si los rivales no ganaron ninguna manga, o 500 si ganaron una. Gana la partida quien tenga m\u00E1s puntos en total, incluidas las primas que se explican a continuaci\u00F3n. Si los totales coinciden, hay empate. S lee la puntuaci\u00F3n."),
            rule_section(:bonuses, "Bazas extra y penalizaciones",
              "Las primas y penalizaciones se anotan encima de la l\u00EDnea. Cuentan para el total, pero no para los 100 puntos necesarios para ganar una manga.",
              "- Cada baza por encima del contrato da 20 puntos en tr\u00E9boles o diamantes, y 30 en corazones, picas o sin triunfo.",
              "- Con el contrato doblado, cada baza extra da 100 puntos sin vulnerabilidad o 200 siendo vulnerable. Si est\u00E1 redoblado, da 200 o 400.",
              "- Cumplir un contrato doblado a\u00F1ade 50 puntos; cumplir uno redoblado, 100.",
              "- Declarar y cumplir un peque\u00F1o slam, un contrato de nivel 6, a\u00F1ade 500 puntos o 750 siendo vulnerable. Un gran slam, de nivel 7, a\u00F1ade 1000 o 1500.",
              "Si no alcanzas las bazas prometidas, los rivales reciben puntos por cada baza que te falte:",
              "- Sin doblar: 50 por baza si no eres vulnerable, o 100 si lo eres.",
              "- Doblado y sin vulnerabilidad: 100 por la primera, 200 por la segunda y tercera, y 300 por cada una posterior.",
              "- Doblado y vulnerable: 200 por la primera y 300 por cada una posterior.",
              "- Redoblado: el doble de la penalizaci\u00F3n correspondiente a un contrato doblado."),
            rule_section(:honors, "Honores",
              "Una pareja tambi\u00E9n puede ganar una prima por ciertas cartas en una sola mano, aunque est\u00E9 defendiendo:",
              "- Cuatro de los cinco triunfos m\u00E1s altos \u2014 as, rey, dama, jota y diez \u2014 dan 100 puntos. Los cinco dan 150.",
              "- En un contrato sin triunfo, tener los cuatro ases en una mano da 150 puntos.",
              "Se anotan encima de la l\u00EDnea. Puedes desactivar los honores en los ajustes de la mesa."),
            rule_section(:variants, "Comparaci\u00F3n con una puntuaci\u00F3n estimada",
              "En los ajustes puedes sustituir el rubber por una serie de 4, 8, 12, 16 o 24 repartos; por defecto son 8. Cada reparto se punt\u00FAa por separado. Su n\u00FAmero determina qui\u00E9n reparte y la vulnerabilidad, que puedes consultar con V.",
              "Un contrato que d\u00E9 al menos 100 puntos por bazas prometidas recibe una prima de manga: 300 sin vulnerabilidad o 500 siendo vulnerable. Un contrato menor recibe 50. Las bazas extra, los doblos, los slams y las penalizaciones mantienen los valores anteriores. No hay honores ni prima de rubber.",
              "El resultado se compara con una referencia convencional, calculada a partir de los puntos de honor de la pareja m\u00E1s fuerte y su vulnerabilidad. Es una estimaci\u00F3n, no el resultado de otra mesa. No tiene en cuenta la longitud de los palos ni c\u00F3mo se complementan las manos.",
              "Por ejemplo, con 26 puntos de honor la referencia es 400 sin vulnerabilidad o 600 siendo vulnerable. Si cada pareja tiene 20, la referencia es cero. Un reparto en el que todos pasan tambi\u00E9n se compara: su resultado real es cero.",
              "Hay dos formas de puntuar la comparaci\u00F3n:",
              "- IMP: una diferencia de hasta 10 puntos no da nada; de 20 a 40 da 1 IMP, de 50 a 80 da 2 y de 90 a 120 da 3. Las diferencias mayores dan m\u00E1s, hasta un m\u00E1ximo de 24. Los recibe la pareja que supera la referencia.",
              "- Puntos de match: superar la referencia da 2 puntos a esa pareja y 0 a la otra. Igualarla da 1 a cada una. S presenta tambi\u00E9n el total como porcentaje de los puntos posibles.",
              "Al terminar los repartos acordados, gana la pareja con m\u00E1s puntos. Si tiene los mismos que la otra, la partida acaba en empate."),
            rule_section(:bots, "Subastar con un bot",
              "El bot utiliza su propia mano, las cartas descubiertas del muerto, la subasta y las cartas jugadas. Estas son algunas de sus aperturas naturales:",
              "- 1 sin triunfo indica una mano equilibrada de 15\u201317 puntos de honor; 2 sin triunfo, de 20\u201321.",
              "- 1 coraz\u00F3n o 1 pica suele indicar al menos 12 puntos y cinco cartas de ese palo. Sin cinco corazones ni cinco picas, abre un palo menor.",
              "- 2 diamantes, 2 corazones o 2 picas indica seis cartas del palo y 6\u201310 puntos.",
              "Subir tu palo indica apoyo. Una subida al nivel 2 es d\u00E9bil; al nivel 3 invita a manga. Los bots no doblan."),
            rule_section(:controls, "Atajos de teclado",
              "Flechas: recorrer cartas o declaraciones.",
              "Intro: hacer la declaraci\u00F3n elegida o jugar la carta.",
              "B: elegir declaraci\u00F3n en tu turno de subasta; fuera de \u00E9l, leerla.",
              "L: leer la subasta.",
              "Ctrl+L: consultar la subasta.",
              "H: leer tu mano y puntos de honor.",
              "D: leer las cartas del muerto.",
              "Tab: cambiar de lista de cartas.",
              "Z: buscar la siguiente carta v\u00E1lida; jugarla si es la \u00FAnica.",
              "May\u00FAs+Z: buscar la carta v\u00E1lida anterior.",
              "K: leer el contrato y las bazas del declarante.",
              "C: leer la baza actual.",
              "Ctrl+C: consultar la baza actual.",
              "F: leer el palo de salida.",
              "P: leer la baza anterior.",
              "I: leer tu posici\u00F3n, compa\u00F1ero y papel.",
              "V: leer reparto, vulnerabilidad y contrato.",
              "S: leer la puntuaci\u00F3n.",
              "T: leer a qui\u00E9n le toca.",
              "May\u00FAs+C: ordenar cartas por palo.",
              "May\u00FAs+H: ordenar por valor.",
              "May\u00FAs+M: recuperar el orden recibido.")
