          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0431\u0440\u0438\u0434\u0436 \u0438\u0433\u0440\u0430\u044E\u0442 \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C, \u0434\u0432\u0443\u043C\u044F \u043F\u0430\u0440\u0430\u043C\u0438. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B \u0441 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u043C \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442\u0435 \u0432 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0435 \u0438 \u043E\u0431\u0435\u0449\u0430\u0435\u0442\u0435 \u0432\u0437\u044F\u0442\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0432\u0437\u044F\u0442\u043E\u043A. \u0412\u0437\u044F\u0442\u043A\u0430 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442: \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043A\u043B\u0430\u0434\u0451\u0442 \u043E\u0434\u043D\u0443. \u041F\u0430\u0440\u0430, \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E, \u0441\u0442\u0430\u0440\u0430\u0435\u0442\u0441\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0441\u0432\u043E\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043C\u0435\u0448\u0430\u044E\u0442 \u0435\u0439.",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0433\u0440\u0430 \u0438\u0434\u0451\u0442 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u043E\u0431\u0431\u0435\u0440\u0430: \u043E\u0434\u043D\u0430 \u0438\u0437 \u043F\u0430\u0440 \u0434\u043E\u043B\u0436\u043D\u0430 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u0434\u0432\u0430 \u0433\u0435\u0439\u043C\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u0432\u0441\u0435\u0433\u043E \u043C\u0430\u0442\u0447\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u043E\u0431\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u043E\u0447\u043A\u043E\u0432, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0441\u043B\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u0433\u0435\u0439\u043C\u043E\u0432."),
            rule_section(:deal, "\u0412\u0430\u0448\u0438 \u043A\u0430\u0440\u0442\u044B \u0438 \u043F\u0430\u0440\u0442\u043D\u0451\u0440",
              "\u0421\u0435\u0432\u0435\u0440 \u0438\u0433\u0440\u0430\u0435\u0442 \u0441 \u042E\u0433\u043E\u043C, \u0412\u043E\u0441\u0442\u043E\u043A \u2014 \u0441 \u0417\u0430\u043F\u0430\u0434\u043E\u043C. \u041F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u0432 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u0432\u044B\u0431\u043E\u0440 \u043A\u043E\u043C\u0430\u043D\u0434 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C. \u0425\u043E\u0434\u044B \u0438\u0434\u0443\u0442 \u0432 \u043F\u043E\u0440\u044F\u0434\u043A\u0435 \u0421\u0435\u0432\u0435\u0440, \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 I \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0432\u0430\u0448\u0435 \u043C\u0435\u0441\u0442\u043E \u0438 \u0438\u043C\u044F \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 13 \u043A\u0430\u0440\u0442. \u0412 \u043A\u0430\u0436\u0434\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0441\u0442\u0430\u0440\u0448\u0435 \u0432\u0441\u0435\u0445 \u0442\u0443\u0437, \u0437\u0430\u0442\u0435\u043C \u0438\u0434\u0443\u0442 \u043A\u043E\u0440\u043E\u043B\u044C, \u0434\u0430\u043C\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0441\u044F\u0442\u043A\u0430 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0434\u043E \u0434\u0432\u043E\u0439\u043A\u0438. \u041F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438\u043B\u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 H, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0435\u0451 \u0446\u0435\u043B\u0438\u043A\u043E\u043C.",
              "\u041F\u0440\u0438 \u0447\u0442\u0435\u043D\u0438\u0438 \u0440\u0443\u043A\u0438 \u0442\u0430\u043A\u0436\u0435 \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B: 4 \u0437\u0430 \u0442\u0443\u0437\u0430, 3 \u0437\u0430 \u043A\u043E\u0440\u043E\u043B\u044F, 2 \u0437\u0430 \u0434\u0430\u043C\u0443 \u0438 1 \u0437\u0430 \u0432\u0430\u043B\u0435\u0442\u0430. \u041E\u043D\u0438 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u043E\u0446\u0435\u043D\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u0440\u0443\u043A\u0438 \u0434\u043B\u044F \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438, \u043D\u043E \u043D\u0435 \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043A \u0441\u0447\u0451\u0442\u0443 \u043C\u0430\u0442\u0447\u0430."),
            rule_section(:auction, "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F",
              "\u041F\u0435\u0440\u0432\u044B\u043C \u0434\u0435\u043B\u0430\u0435\u0442 \u0437\u0430\u044F\u0432\u043A\u0443 \u0441\u0434\u0430\u044E\u0449\u0438\u0439. \u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u044F\u0432\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u0437\u0430\u044F\u0432\u043E\u043A \u043C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 B.",
              "\u041D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0447\u0438\u0441\u043B\u0430 \u043E\u0442 1 \u0434\u043E 7 \u0438 \u043C\u0430\u0441\u0442\u0438 \u043B\u0438\u0431\u043E \u0441\u043B\u043E\u0432 \u00AB\u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F\u00BB. \u041F\u0440\u0438\u0431\u0430\u0432\u044C\u0442\u0435 \u043A \u0447\u0438\u0441\u043B\u0443 \u0448\u0435\u0441\u0442\u044C, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0432\u0437\u044F\u0442\u043E\u043A: 1 \u0447\u0435\u0440\u0432\u0430 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0441\u0435\u043C\u044C, \u0430 4 \u043F\u0438\u043A\u0438 \u2014 \u0434\u0435\u0441\u044F\u0442\u044C. \u041D\u0430\u0437\u0432\u0430\u043D\u043D\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u043A\u043E\u0437\u044B\u0440\u043D\u043E\u0439, \u0438 \u0435\u0451 \u043A\u0430\u0440\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0431\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0434\u0440\u0443\u0433\u0438\u0445 \u043C\u0430\u0441\u0442\u0435\u0439. \u0412 \u0431\u0435\u0441\u043A\u043E\u0437\u044B\u0440\u043D\u043E\u043C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0435 \u0442\u0430\u043A\u043E\u0433\u043E \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043D\u0435\u0442 \u043D\u0438 \u0443 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438.",
              "\u041D\u043E\u0432\u043E\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u0432\u044B\u0448\u0435 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E. \u041F\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043C\u0430\u0441\u0442\u0438 \u0438\u0434\u0443\u0442 \u043F\u043E \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u043D\u0438\u044E: \u0442\u0440\u0435\u0444\u044B, \u0431\u0443\u0431\u043D\u044B, \u0447\u0435\u0440\u0432\u044B, \u043F\u0438\u043A\u0438, \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F. \u0411\u043E\u043B\u0435\u0435 \u0432\u044B\u0441\u043E\u043A\u0438\u0439 \u0443\u0440\u043E\u0432\u0435\u043D\u044C \u043F\u0440\u0435\u0432\u043E\u0441\u0445\u043E\u0434\u0438\u0442 \u0432\u0441\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043D\u0430 \u0431\u043E\u043B\u0435\u0435 \u043D\u0438\u0437\u043A\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 1 \u043F\u0438\u043A\u0438 \u043C\u043E\u0436\u043D\u043E, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043D\u0430\u0437\u043D\u0430\u0447\u0438\u0442\u044C 1 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u0438\u043B\u0438 2 \u0442\u0440\u0435\u0444\u044B.",
              "\u041A\u0440\u043E\u043C\u0435 \u043D\u043E\u0432\u043E\u0433\u043E \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B:",
              "- \u041F\u0430\u0441: \u0441\u043B\u043E\u0432\u043E \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443. \u0415\u0441\u043B\u0438 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0432\u0435\u0440\u043D\u0451\u0442\u0441\u044F \u043A \u0432\u0430\u043C, \u0432\u044B \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E.",
              "- \u041A\u043E\u043D\u0442\u0440\u0430: \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u043D\u0430\u0433\u0440\u0430\u0434\u0443 \u0437\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432 \u0438 \u0448\u0442\u0440\u0430\u0444 \u0437\u0430 \u0435\u0433\u043E \u043D\u0435\u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435. \u041A\u043E\u043D\u0442\u0440\u0443 \u0434\u0430\u044E\u0442 \u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430, \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043C\u043E\u0433\u043B\u0438 \u0431\u044B\u0442\u044C \u043F\u0430\u0441\u044B.",
              "- \u0420\u0435\u043A\u043E\u043D\u0442\u0440\u0430: \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0440\u044B \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043D\u0430 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0432\u0430\u0448\u0435\u0439 \u043F\u0430\u0440\u044B \u0435\u0449\u0451 \u0440\u0430\u0437 \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442 \u0441\u0442\u0430\u0432\u043A\u0438. \u041D\u043E\u0432\u043E\u0435, \u0431\u043E\u043B\u0435\u0435 \u0432\u044B\u0441\u043E\u043A\u043E\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u043A\u043E\u043D\u0442\u0440\u0443 \u0438\u043B\u0438 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u0443.",
              "\u0422\u0440\u0438 \u043F\u0430\u0441\u0430 \u043F\u043E\u0434\u0440\u044F\u0434 \u043F\u043E\u0441\u043B\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C. \u0415\u0441\u043B\u0438 \u0441 \u0441\u0430\u043C\u043E\u0433\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0430\u0441\u0443\u044E\u0442 \u0432\u0441\u0435 \u0447\u0435\u0442\u0432\u0435\u0440\u043E, \u0441\u0434\u0430\u0447\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u043E\u0447\u043A\u043E\u0432, \u0430 \u0441\u0434\u0430\u044E\u0449\u0438\u043C \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A.",
              "L \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E \u0446\u0435\u043B\u0438\u043A\u043E\u043C, \u0430 Ctrl+L \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0438 \u043F\u043E \u043E\u0434\u043D\u043E\u0439."),
            rule_section(:play, "\u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0438 \u0431\u043E\u043B\u0432\u0430\u043D",
              "\u0420\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u043C \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0442\u043E\u0442 \u0438\u0437 \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0435\u0439 \u043F\u0430\u0440\u044B, \u043A\u0442\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u043D\u0430\u0437\u0432\u0430\u043B \u043C\u0430\u0441\u0442\u044C \u0438\u0442\u043E\u0433\u043E\u0432\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u043B\u0438\u0431\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u0437\u0430\u044F\u0432\u0438\u043B \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F, \u0435\u0441\u043B\u0438 \u044D\u0442\u043E \u0431\u0435\u0441\u043A\u043E\u0437\u044B\u0440\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442. \u0415\u0441\u043B\u0438 \u0421\u0435\u0432\u0435\u0440 \u043D\u0430\u0437\u043D\u0430\u0447\u0438\u043B 1 \u0447\u0435\u0440\u0432\u0443, \u0430 \u042E\u0433 \u0437\u0430\u0442\u0435\u043C 4 \u0447\u0435\u0440\u0432\u044B, \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0421\u0435\u0432\u0435\u0440.",
              "\u041F\u0435\u0440\u0432\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u043A\u043B\u0430\u0434\u0451\u0442 \u0438\u0433\u0440\u043E\u043A, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u043C. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443 \u0438 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0431\u043E\u043B\u0432\u0430\u043D\u043E\u043C. \u0412\u0441\u0435 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0435\u0433\u043E \u043A\u0430\u0440\u0442\u044B \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 D, \u043D\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0438\u0445 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439. K \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0438 \u0447\u0438\u0441\u043B\u043E \u0432\u0437\u044F\u0442\u043E\u043A \u0435\u0433\u043E \u043F\u0430\u0440\u044B.",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0435\u0451 Enter. \u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043C\u0430\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0432\u0437\u044F\u0442\u043A\u0438, \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0418\u043D\u0430\u0447\u0435 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E. \u0412\u0437\u044F\u0442\u043A\u0443 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C, \u0430 \u0435\u0441\u043B\u0438 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u043D\u0435\u0442 \u2014 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u0432\u044B\u0445\u043E\u0434\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443.",
              "\u041A\u043E\u0433\u0434\u0430 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0431\u043E\u043B\u0432\u0430\u043D\u0430, \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043A \u0441\u043F\u0438\u0441\u043A\u0443 \u0435\u0433\u043E \u043A\u0430\u0440\u0442 \u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0434\u043D\u0443 \u0438\u0437 \u043D\u0438\u0445. Z \u0441\u0440\u0430\u0437\u0443 \u043D\u0430\u0445\u043E\u0434\u0438\u0442 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432 \u043D\u0443\u0436\u043D\u043E\u0439 \u0440\u0443\u043A\u0435, Shift+Z \u0438\u0449\u0435\u0442 \u0432 \u043E\u0431\u0440\u0430\u0442\u043D\u043E\u043C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0438. \u0415\u0441\u043B\u0438 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u0430 \u043A\u0430\u0440\u0442\u0430, Z \u0441\u0440\u0430\u0437\u0443 \u0435\u0451 \u0438\u0433\u0440\u0430\u0435\u0442.",
              "C \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443, F \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u043C\u0430\u0441\u0442\u044C \u0432\u044B\u0445\u043E\u0434\u0430, \u0430 P \u2014 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443 \u0438 \u0435\u0451 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F. \u041F\u043E\u0441\u043B\u0435 \u0432\u0441\u0435\u0445 13 \u0432\u0437\u044F\u0442\u043E\u043A \u043F\u043E\u0434\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438, \u0438 \u043A\u0430\u0440\u0442\u044B \u0441\u0434\u0430\u0451\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A."),
            rule_section(:scoring, "\u041E\u0447\u043A\u0438 \u0438 \u0440\u043E\u0431\u0431\u0435\u0440",
              "\u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u044B\u0435 \u0432\u0437\u044F\u0442\u043A\u0438 \u0441\u0432\u0435\u0440\u0445 \u043F\u0435\u0440\u0432\u044B\u0445 \u0448\u0435\u0441\u0442\u0438:",
              "- \u041F\u043E 20 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0443 \u0432 \u0442\u0440\u0435\u0444\u0430\u0445 \u0438\u043B\u0438 \u0431\u0443\u0431\u043D\u0430\u0445.",
              "- \u041F\u043E 30 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0443 \u0432 \u0447\u0435\u0440\u0432\u0430\u0445 \u0438\u043B\u0438 \u043F\u0438\u043A\u0430\u0445.",
              "- \u0411\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F: 40 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E \u0438 \u043F\u043E 30 \u0437\u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435.",
              "\u041A\u043E\u043D\u0442\u0440\u0430 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u044D\u0442\u0438 \u043E\u0447\u043A\u0438, \u0430 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u0430 \u0443\u043C\u043D\u043E\u0436\u0430\u0435\u0442 \u0438\u0445 \u043D\u0430 \u0447\u0435\u0442\u044B\u0440\u0435. \u0418\u0445 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439. \u041D\u0430\u0431\u0440\u0430\u0432 \u0442\u0430\u043C 100 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043E\u0434\u043D\u0443 \u0438\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0434\u0430\u0447, \u043F\u0430\u0440\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0433\u0435\u0439\u043C. \u0414\u043B\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0433\u0435\u0439\u043C\u0430 \u043E\u0431\u0435 \u043F\u0430\u0440\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u043D\u0430\u0431\u0438\u0440\u0430\u0442\u044C \u043E\u0447\u043A\u0438 \u0437\u0430\u043D\u043E\u0432\u043E.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0435 2 \u0447\u0435\u0440\u0432\u044B \u0434\u0430\u044E\u0442 60 \u043E\u0447\u043A\u043E\u0432 \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439. \u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043F\u043E\u0437\u0434\u043D\u0435\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 1 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 40 \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0433\u0435\u0439\u043C, \u0435\u0441\u043B\u0438 \u0434\u043E \u044D\u0442\u043E\u0433\u043E \u0435\u0433\u043E \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0430 \u043D\u0438 \u043E\u0434\u043D\u0430 \u0438\u0437 \u043F\u0430\u0440.",
              "\u0412\u044B\u0438\u0433\u0440\u0430\u0432 \u0433\u0435\u0439\u043C, \u043F\u0430\u0440\u0430 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0439 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u043E\u0431\u0431\u0435\u0440\u0430. \u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0435\u0451 \u043F\u0440\u0435\u043C\u0438\u0438 \u0438 \u0448\u0442\u0440\u0430\u0444\u044B \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044E\u0442\u0441\u044F. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 V \u0447\u0438\u0442\u0430\u0435\u0442 \u043D\u043E\u043C\u0435\u0440 \u0441\u0434\u0430\u0447\u0438 \u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u044C \u043F\u0430\u0440.",
              "\u0412\u0442\u043E\u0440\u043E\u0439 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0439 \u0433\u0435\u0439\u043C \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0440\u043E\u0431\u0431\u0435\u0440. \u0417\u0430 \u043D\u0435\u0433\u043E \u043F\u0430\u0440\u0430 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 700 \u043E\u0447\u043A\u043E\u0432, \u0435\u0441\u043B\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043D\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0433\u0435\u0439\u043C\u0430, \u0438\u043B\u0438 500, \u0435\u0441\u043B\u0438 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043E\u0434\u0438\u043D. \u041C\u0430\u0442\u0447 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0430\u0440\u0430 \u0441 \u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u043E\u0431\u0449\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043F\u0440\u0435\u043C\u0438\u0438 \u0438\u0437 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0440\u0430\u0437\u0434\u0435\u043B\u0430. \u041F\u0440\u0438 \u0440\u0430\u0432\u043D\u044B\u0445 \u0441\u0443\u043C\u043C\u0430\u0445 \u2014 \u043D\u0438\u0447\u044C\u044F. \u0421\u0447\u0451\u0442 \u0447\u0438\u0442\u0430\u0435\u0442 S."),
            rule_section(:bonuses, "\u041B\u0438\u0448\u043D\u0438\u0435 \u0432\u0437\u044F\u0442\u043A\u0438, \u043F\u0440\u0435\u043C\u0438\u0438 \u0438 \u0448\u0442\u0440\u0430\u0444\u044B",
              "\u041F\u0440\u0435\u043C\u0438\u0438 \u0438 \u0448\u0442\u0440\u0430\u0444\u044B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043D\u0430\u0434 \u0447\u0435\u0440\u0442\u043E\u0439. \u041E\u043D\u0438 \u0432\u0445\u043E\u0434\u044F\u0442 \u0432 \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442, \u043D\u043E \u043D\u0435 \u043F\u0440\u0438\u0431\u043B\u0438\u0436\u0430\u044E\u0442 \u043A \u0441\u0442\u0430 \u043E\u0447\u043A\u0430\u043C, \u043D\u0443\u0436\u043D\u044B\u043C \u0434\u043B\u044F \u0433\u0435\u0439\u043C\u0430.",
              "- \u041A\u0430\u0436\u0434\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0441\u0432\u0435\u0440\u0445 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0434\u0430\u0451\u0442 20 \u043E\u0447\u043A\u043E\u0432 \u0432 \u0442\u0440\u0435\u0444\u0430\u0445 \u0438\u043B\u0438 \u0431\u0443\u0431\u043D\u0430\u0445 \u0438 30 \u0432 \u0447\u0435\u0440\u0432\u0430\u0445, \u043F\u0438\u043A\u0430\u0445 \u0438\u043B\u0438 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F.",
              "- \u0412 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0435 \u043F\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u043B\u0438\u0448\u043D\u044F\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0434\u0430\u0451\u0442 100 \u043E\u0447\u043A\u043E\u0432 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 200 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438. \u041F\u043E\u0434 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u2014 200 \u0438\u043B\u0438 400.",
              "- \u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u043F\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 50 \u043E\u0447\u043A\u043E\u0432, \u043F\u043E\u0434 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u2014 100.",
              "- \u0417\u0430 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044B\u0439 \u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043C\u0430\u043B\u044B\u0439 \u0448\u043B\u0435\u043C, \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 6, \u0434\u0430\u0451\u0442\u0441\u044F 500 \u043E\u0447\u043A\u043E\u0432 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 750 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438. \u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u0448\u043B\u0435\u043C \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 7 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E 1000 \u0438\u043B\u0438 1500.",
              "\u0415\u0441\u043B\u0438 \u0432\u044B \u043D\u0435 \u043D\u0430\u0431\u0440\u0430\u043B\u0438 \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u044B\u0435 \u0432\u0437\u044F\u0442\u043A\u0438, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0443\u044E:",
              "- \u0411\u0435\u0437 \u043A\u043E\u043D\u0442\u0440\u044B: \u043F\u043E 50 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u0432\u0430\u0448\u0435\u0439 \u043F\u0430\u0440\u044B \u0438\u043B\u0438 \u043F\u043E 100 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438.",
              "- \u041F\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438: 100 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E, \u043F\u043E 200 \u0437\u0430 \u0432\u0442\u043E\u0440\u0443\u044E \u0438 \u0442\u0440\u0435\u0442\u044C\u044E, \u0437\u0430\u0442\u0435\u043C \u043F\u043E 300.",
              "- \u041F\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438: 200 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E, \u0437\u0430\u0442\u0435\u043C \u043F\u043E 300.",
              "- \u041F\u043E\u0434 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u0439: \u0432\u0434\u0432\u043E\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0448\u0442\u0440\u0430\u0444\u0430 \u043F\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u043E\u0439."),
            rule_section(:honors, "\u041E\u043D\u0451\u0440\u044B",
              "\u0417\u0430 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u0441\u0442\u0430\u0440\u0448\u0438\u0445 \u043A\u0430\u0440\u0442 \u0432 \u043E\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0435 \u043F\u0430\u0440\u0430 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0443\u044E \u043F\u0440\u0435\u043C\u0438\u044E, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442\u0441\u044F:",
              "- \u0427\u0435\u0442\u044B\u0440\u0435 \u0438\u0437 \u043F\u044F\u0442\u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u0445 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u2014 \u0442\u0443\u0437\u0430, \u043A\u043E\u0440\u043E\u043B\u044F, \u0434\u0430\u043C\u044B, \u0432\u0430\u043B\u0435\u0442\u0430 \u0438 \u0434\u0435\u0441\u044F\u0442\u043A\u0438 \u2014 \u0434\u0430\u044E\u0442 100 \u043E\u0447\u043A\u043E\u0432. \u0412\u0441\u0435 \u043F\u044F\u0442\u044C \u0434\u0430\u044E\u0442 150.",
              "- \u0412 \u0431\u0435\u0441\u043A\u043E\u0437\u044B\u0440\u043D\u043E\u043C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0442\u0443\u0437\u0430 \u0432 \u043E\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0435 \u0434\u0430\u044E\u0442 150 \u043E\u0447\u043A\u043E\u0432.",
              "\u041E\u043D\u0451\u0440\u044B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043D\u0430\u0434 \u0447\u0435\u0440\u0442\u043E\u0439. \u0418\u0445 \u043F\u043E\u0434\u0441\u0447\u0451\u0442 \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430."),
            rule_section(:variants, "\u0421\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u0435 \u0441 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u043E\u0432\u043E\u0447\u043D\u044B\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u043C",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u0440\u043E\u0431\u0431\u0435\u0440\u0430 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u0435\u0440\u0438\u044E \u0438\u0437 4, 8, 12, 16 \u0438\u043B\u0438 24 \u0441\u0434\u0430\u0447; \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0445 8. \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0434\u0430\u0447\u0430 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u0415\u0451 \u043D\u043E\u043C\u0435\u0440 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u044C. \u042D\u0442\u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u043F\u043E V.",
              "\u0417\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 100 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u044B\u0435 \u0432\u0437\u044F\u0442\u043A\u0438, \u043F\u043E\u043B\u0430\u0433\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0435\u043C\u0438\u044F \u0437\u0430 \u0433\u0435\u0439\u043C: 300 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 500 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438. \u0417\u0430 \u043C\u0435\u043D\u044C\u0448\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0434\u0430\u0451\u0442\u0441\u044F 50. \u041B\u0438\u0448\u043D\u0438\u0435 \u0432\u0437\u044F\u0442\u043A\u0438, \u043A\u043E\u043D\u0442\u0440\u044B, \u0448\u043B\u0435\u043C\u044B \u0438 \u0448\u0442\u0440\u0430\u0444\u044B \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u043A\u0430\u043A \u0440\u0430\u043D\u044C\u0448\u0435. \u041E\u043D\u0451\u0440\u043E\u0432 \u0438 \u043F\u0440\u0435\u043C\u0438\u0438 \u0437\u0430 \u0440\u043E\u0431\u0431\u0435\u0440 \u043D\u0435\u0442.",
              "\u041F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441 \u0443\u0441\u043B\u043E\u0432\u043D\u043E\u0439 \u043E\u0446\u0435\u043D\u043A\u043E\u0439, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0441\u0443\u043C\u043C\u044B \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B \u0443 \u0431\u043E\u043B\u0435\u0435 \u0441\u0438\u043B\u044C\u043D\u043E\u0439 \u043F\u0430\u0440\u044B \u0438 \u0435\u0451 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438. \u042D\u0442\u043E \u043D\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0437\u0430 \u0434\u0440\u0443\u0433\u0438\u043C \u0441\u0442\u043E\u043B\u043E\u043C. \u041E\u0446\u0435\u043D\u043A\u0430 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0434\u043B\u0438\u043D\u0443 \u043C\u0430\u0441\u0442\u0435\u0439 \u0438 \u0442\u043E, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0445\u043E\u0440\u043E\u0448\u043E \u0440\u0443\u043A\u0438 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u0432 \u0434\u043E\u043F\u043E\u043B\u043D\u044F\u044E\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u0438 26 \u043E\u0447\u043A\u0430\u0445 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 400 \u0431\u0435\u0437 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 600 \u043F\u0440\u0438 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438. \u0415\u0441\u043B\u0438 \u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u043F\u0430\u0440\u044B \u043F\u043E 20, \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440 \u0440\u0430\u0432\u0435\u043D \u043D\u0443\u043B\u044E. \u0421\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0441\u0434\u0430\u0447\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0432\u0441\u0435 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438: \u0435\u0451 \u0444\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u043D\u043E\u043B\u044C.",
              "\u0415\u0441\u0442\u044C \u0434\u0432\u0430 \u0441\u043F\u043E\u0441\u043E\u0431\u0430 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430:",
              "- IMP: \u0440\u0430\u0437\u043D\u0438\u0446\u0430 \u0434\u043E 10 \u043E\u0447\u043A\u043E\u0432 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0434\u0430\u0451\u0442; 20\u201340 \u0434\u0430\u0451\u0442 1 IMP, 50\u201380 \u2014 2, 90\u2013120 \u2014 3. \u0417\u0430 \u0431\u043E\u043B\u0435\u0435 \u043A\u0440\u0443\u043F\u043D\u044B\u0435 \u0440\u0430\u0437\u043B\u0438\u0447\u0438\u044F \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u0435\u0442\u0441\u044F \u0431\u043E\u043B\u044C\u0448\u0435, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 24 IMP. \u0418\u0445 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u0430\u0440\u0430, \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u043B\u0443\u0447\u0448\u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430.",
              "- \u041C\u0430\u0442\u0447\u043F\u043E\u0439\u043D\u0442\u044B: \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043B\u0443\u0447\u0448\u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u044D\u0442\u043E\u0439 \u043F\u0430\u0440\u0435 2 \u043E\u0447\u043A\u0430, \u0430 \u0434\u0440\u0443\u0433\u043E\u0439 \u2014 0. \u041F\u0440\u0438 \u0442\u043E\u0447\u043D\u043E\u043C \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0438 \u043A\u0430\u0436\u0434\u0430\u044F \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E 1. S \u0442\u0430\u043A\u0436\u0435 \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0447\u0451\u0442 \u0432 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430\u0445 \u043E\u0442 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u043E\u0447\u043A\u043E\u0432.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u0434\u0430\u0447\u0438 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0430\u0440\u0430 \u0441 \u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439. \u0420\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u043E \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0438\u0447\u044C\u044E."),
            rule_section(:bots, "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F \u0441 \u0431\u043E\u0442\u043E\u043C",
              "\u0411\u043E\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0441\u0432\u043E\u0438 \u043A\u0430\u0440\u0442\u044B, \u043E\u0442\u043A\u0440\u044B\u0442\u0443\u044E \u0440\u0443\u043A\u0443 \u0431\u043E\u043B\u0432\u0430\u043D\u0430, \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0438 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B. \u041E\u043D \u0442\u043E\u0440\u0433\u0443\u0435\u0442\u0441\u044F \u0432 \u043D\u0430\u0442\u0443\u0440\u0430\u043B\u044C\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435. \u041E\u0441\u043D\u043E\u0432\u043D\u044B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F \u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442:",
              "- 1 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F: \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u0441 15\u201317 \u043E\u0447\u043A\u0430\u043C\u0438 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B; 2 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F: 20\u201321 \u043E\u0447\u043A\u043E.",
              "- 1 \u0447\u0435\u0440\u0432\u0430 \u0438\u043B\u0438 1 \u043F\u0438\u043A\u0430: \u043E\u0431\u044B\u0447\u043D\u043E \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 12 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043F\u044F\u0442\u044C \u043A\u0430\u0440\u0442 \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0411\u0435\u0437 \u043F\u044F\u0442\u0438 \u0447\u0435\u0440\u0432\u0435\u0439 \u0438\u043B\u0438 \u043F\u0438\u043A \u0431\u043E\u0442 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043C\u043B\u0430\u0434\u0448\u0443\u044E \u043C\u0430\u0441\u0442\u044C.",
              "- 2 \u0431\u0443\u0431\u043D\u044B, 2 \u0447\u0435\u0440\u0432\u044B \u0438\u043B\u0438 2 \u043F\u0438\u043A\u0438: \u0448\u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u043C\u0430\u0441\u0442\u0438 \u0438 6\u201310 \u043E\u0447\u043A\u043E\u0432.",
              "\u041F\u043E\u0434\u043D\u044F\u0442\u0438\u0435 \u0432\u0430\u0448\u0435\u0439 \u043C\u0430\u0441\u0442\u0438 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0443. \u041F\u043E\u0434\u043D\u044F\u0442\u0438\u0435 \u0434\u043E \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u0443\u0440\u043E\u0432\u043D\u044F \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u0430\u0431\u0443\u044E \u0440\u0443\u043A\u0443, \u0434\u043E \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u043F\u0440\u0438\u0433\u043B\u0430\u0448\u0430\u0435\u0442 \u043A \u0433\u0435\u0439\u043C\u0443. \u0411\u043E\u0442\u044B \u043D\u0435 \u0434\u0430\u044E\u0442 \u043A\u043E\u043D\u0442\u0440\u0443."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043A\u0430\u0440\u0442 \u0438\u043B\u0438 \u0437\u0430\u044F\u0432\u043E\u043A.",
              "Enter: \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0430\u044F \u0437\u0430\u044F\u0432\u043A\u0430 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442\u0430.",
              "B: \u0432\u044B\u0431\u043E\u0440 \u0437\u0430\u044F\u0432\u043A\u0438 \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438; \u0438\u043D\u0430\u0447\u0435 \u0447\u0442\u0435\u043D\u0438\u0435 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438.",
              "L: \u0447\u0442\u0435\u043D\u0438\u0435 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438.",
              "Ctrl+L: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0437\u0430\u044F\u0432\u043E\u043A.",
              "H: \u0432\u0430\u0448\u0430 \u0440\u0443\u043A\u0430 \u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B.",
              "D: \u043A\u0430\u0440\u0442\u044B \u0431\u043E\u043B\u0432\u0430\u043D\u0430.",
              "Tab: \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u043C\u0435\u0436\u0434\u0443 \u0441\u043F\u0438\u0441\u043A\u0430\u043C\u0438 \u043A\u0430\u0440\u0442.",
              "Z: \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430\u044F \u043A\u0430\u0440\u0442\u0430; \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F, \u0441\u0440\u0430\u0437\u0443 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0435\u0451.",
              "Shift+Z: \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0430\u044F \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430\u044F \u043A\u0430\u0440\u0442\u0430.",
              "K: \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0438 \u0447\u0438\u0441\u043B\u043E \u0432\u0437\u044F\u0442\u043E\u043A \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E.",
              "C: \u0442\u0435\u043A\u0443\u0449\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430.",
              "Ctrl+C: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438.",
              "F: \u043C\u0430\u0441\u0442\u044C \u0432\u044B\u0445\u043E\u0434\u0430.",
              "P: \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430.",
              "I: \u0432\u0430\u0448\u0435 \u043C\u0435\u0441\u0442\u043E, \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u0438 \u0440\u043E\u043B\u044C.",
              "V: \u0441\u0434\u0430\u0447\u0430, \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u044C \u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442.",
              "S: \u0441\u0447\u0451\u0442.",
              "T: \u0447\u0435\u0439 \u0445\u043E\u0434.",
              "Shift+C: \u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u043A\u0430 \u043F\u043E \u043C\u0430\u0441\u0442\u0438.",
              "Shift+H: \u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u043A\u0430 \u043F\u043E \u0441\u0442\u0430\u0440\u0448\u0438\u043D\u0441\u0442\u0432\u0443.",
              "Shift+M: \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043A\u0430\u0440\u0442.")
          ]
        end
      end
    end
    include GeneratedRulebook
  end
end
